      ]
    },
    {
      "id": "C1-05",
      "ja": "あなたをずっと探してた",
      "budget": {
        "min": 11,
        "max": 11
      },
      "pattern": [
        6,
        5
      ]
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "爱究竟是从何处降临的呢"
        },
        {
          "id": "C1-02",
          "zh": "我向自己的胸口轻声叩问"
        },
        {
          "id": "C1-03",
          "zh": "虚假的东西我毫无兴趣啊"
        },
        {
          "id": "C1-04",
          "zh": "只想去寻找到真实的那份"
        },
        {
          "id": "C1-05",
          "zh": "我一直都在寻找着你呀"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "爱情到底是从什么地方而来的呢"
        },
        {
          "id": "C1-02",
          "zh": "我问自己的心它到底在哪里"
        },
        {
          "id": "C1-03",
          "zh": "假的东西我根本就不会在意"
        },
        {
          "id": "C1-04",
          "zh": "我只想去找到那真正的爱"
        },
        {
          "id": "C1-05",
          "zh": "我一直寻找的那个人是你"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "爱从何处 降临人间 无声却很明亮"
        },
        {
          "id": "C1-02",
          "zh": "按着胸口 问自己 听心跳回答"
        },
        {
          "id": "C1-03",
          "zh": "橱窗里的假货 我一眼都不看"
        },
        {
          "id": "C1-04",
          "zh": "真正的爱我要 亲手去找到"
        },
        {
          "id": "C1-05",
          "zh": "人海里我一直 在找你身影"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "爱究竟从何处悄悄降临人间"
        },
        {
          "id": "C1-02",
          "zh": "我轻声问自己心间"
        },
        {
          "id": "C1-03",
          "zh": "虚假的温柔我从来不愿多看一眼"
        },
        {
          "id": "C1-04",
          "zh": "只想凝视那份真实的脸"
        },
        {
          "id": "C1-05",
          "zh": "我一直都在找寻你的出现"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "爱从何来 又往哪去 住进谁的胸口"
        },
        {
          "id": "C1-02",
          "zh": "手贴胸口 轻轻问 心是否诚实"
        },
        {
          "id": "C1-03",
          "zh": "假货摆得再亮 我也只要真的"
        },
        {
          "id": "C1-04",
          "zh": "只想找到真的 眼神不闪躲"
        },
        {
          "id": "C1-05",
          "zh": "找了好久的人 原来就是你"
        }
      ]
    },
    {
      "label": "F",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "爱是从哪里悄悄降临的呢"
        },
        {
          "id": "C1-02",
          "zh": "问自己胸口这颗心"
        },
        {
          "id": "C1-03",
          "zh": "虚假的东西我毫无兴趣"
        },
        {
          "id": "C1-04",
          "zh": "只想凝视真实的光"
        },
        {
          "id": "C1-05",
          "zh": "我一直都在寻找着你"
        }
      ]
    }
  ]
}

